"""Migrated Meridian CRM 4.2 ACC-004 credit-hold release rule."""

from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    """A blocking legacy business-rule validation failure."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _numeric_value(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty or missing values compare as zero."""
    if value == "" or value is None:
        return Decimal("0")
    return Decimal(str(value))


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """
    Release an account credit hold under legacy ACC-004 validation semantics.

    The input account is not modified.
    """
    updated_account = account.copy()

    # Legacy CHAR(1) boolean semantics: only Y denotes an active hold.
    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    credit_limit = _numeric_value(account.get("CRED_LIMIT", ""))

    if credit_limit <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    entity_id = str(account.get("ACCT_ID", "") or "")

    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": entity_id,
        }
    ]
